typedef struct { int uid; const char* cmd; const char* arg; } cli_ctx_t;

int cli_has_permission(cli_ctx_t* ctx) { return ctx->uid == 0; }
void cli_enforce_permission(cli_ctx_t* ctx) { (void)ctx; }
void cli_log_denied(cli_ctx_t* ctx) { (void)ctx; }
void nvs_erase_all(void) {}
void set_admin_password(const char* pw) { (void)pw; }

void cli_handle_factory_reset(cli_ctx_t* ctx)
{
  if (!cli_has_permission(ctx)) {
    cli_log_denied(ctx);
    return;
  }
  cli_enforce_permission(ctx);
  nvs_erase_all();
}

void cli_handle_factory_reset_variant(cli_ctx_t* ctx)
{
  if (!cli_has_permission(ctx)) {
    cli_log_denied(ctx);
    return;
  }
  cli_enforce_permission(ctx);
  nvs_erase_all();
}

void cli_handle_set_password(cli_ctx_t* ctx)
{
  if (!cli_has_permission(ctx)) {
    cli_log_denied(ctx);
    return;
  }
  cli_enforce_permission(ctx);
  set_admin_password(ctx->arg);
}
